const deliveryFees={"George Town":150,"7 Mile Beach":200,"West Bay":250,"Red Bay":200,"Prospect":200,"Spotts":200,"Savannah":250,"Bodden Town":300,"East End":350,"North Side":400};
function collectableRental(p){return !!p?.delivery&&!p.operatorService&&!p.setPart&&["Tools","Power Generation","Attachments","Construction Plant / Equipment","Ground Protection"].includes(p.category)}
function hasCollectableRentals(){return !hasLiftingService()&&cart.some(i=>!i.inSet&&collectableRental(products.find(p=>p.id===i.id)))}
function rentalCollection(){if(hasLiftingService())return "delivery";return hasCollectableRentals()&&$("#rentalCollection")?.value==="pickup"?"pickup":"delivery"}
function deliveryAvailable(i){const p=products.find(p=>p.id===i.id);return !!p?.delivery&&!p.operatorService&&!p.setPart&&!i.inSet}
function bundledAccessoryDelivery(i){const p=products.find(p=>p.id===i.id);if(!p||["Rough Terrain Cranes","Boom Trucks","Telehandlers"].includes(p.category))return false;const id=p.rigging?.family||p.id;return cart.some(line=>{const machine=products.find(p=>p.id===line.id);return ["Rough Terrain Cranes","Boom Trucks","Telehandlers"].includes(machine?.category)&&(p.category==="Attachments"||(machine.addOns||[]).includes(id));})}
function groupedSiteRental(i){return ["plumwall","scaffold","props","mats","ellis"].includes(i.id)}
function chargeableSiteRental(i){return groupedSiteRental(i)&&deliveryAvailable(i)&&!bundledAccessoryDelivery(i)}
function firstSiteRental(i){return cart.find(chargeableSiteRental)===i}
function deliveryEligible(i){const p=products.find(p=>p.id===i.id);return deliveryAvailable(i)&&!bundledAccessoryDelivery(i)&&!(collectableRental(p)&&rentalCollection()==="pickup")&&(groupedSiteRental(i)||!["weekly","monthly"].includes(i.term))}
const hourlyBillingNote="*Additional hours worked outside of the 4 hour minimum will be billed at the current hourly rate*";
function hasHourlyEquipmentService(){return cart.some(i=>i.term==="hourly"&&["Rough Terrain Cranes","Boom Trucks","Telehandlers","Heavy Hauling"].includes(products.find(p=>p.id===i.id)?.category))}
function checkoutTermsText(){const terms=$(".contract").innerText;return hasHourlyEquipmentService()?terms:terms.replace(hourlyBillingNote, "")}
function hasLiftingService(){return cart.some(i=>["Rough Terrain Cranes","Boom Trucks","Telehandlers"].includes(products.find(p=>p.id===i.id)?.category))}
function needsDeliveryAddress(){return hasLiftingService()||cart.some(i=>deliveryAvailable(i)&&(!collectableRental(products.find(p=>p.id===i.id))||rentalCollection()==="delivery"))}
function needsJobDetails(){return visibleCart().length>0}
// Hourly quantities are billable hours; daily quantities are equipment units.
function deliveryQuantity(i){return i.term==="hourly"?1:i.qty}
function itemDeliveryEstimate(i){if(!deliveryEligible(i))return 0;if(groupedSiteRental(i)&&!firstSiteRental(i))return 0;const area=$("#areaSelect").value;if(Object.hasOwn(deliveryFees,area))return deliveryFees[area]*(groupedSiteRental(i)?1:deliveryQuantity(i));return null}
function collectionEligible(i){const p=products.find(p=>p.id===i.id);return deliveryAvailable(i)&&rentalCollection()!=="pickup"&&!["Rough Terrain Cranes","Boom Trucks","Telehandlers"].includes(p?.category)&&!bundledAccessoryDelivery(i)}
function collectionEstimate(){if(!cart.some(collectionEligible))return 0;const area=$("#areaSelect").value;return Object.hasOwn(deliveryFees,area)?deliveryFees[area]:null}
function outboundDeliveryEstimate(){let total=0;for(const i of cart){const fee=itemDeliveryEstimate(i);if(fee===null)return null;total+=fee}return total}
function deliveryEstimate(){const delivery=outboundDeliveryEstimate(),pickup=collectionEstimate();return delivery===null||pickup===null?null:delivery+pickup}

function deliveryLine(i){if(!deliveryAvailable(i))return "";if(groupedSiteRental(i)){if(rentalCollection()==="pickup")return "Customer pickup and return · No delivery or collection charge";if(bundledAccessoryDelivery(i))return "Included with equipment delivery · No additional delivery or pickup fee";if(!firstSiteRental(i))return "Included in the shared braces / scaffolding / shores / mats delivery";const rate=deliveryFees[$("#areaSelect").value];return rate===undefined?"One delivery charge for the entire grouped rental order · Select area":`Grouped rental order: delivery ${money(rate)}, charged once regardless of quantity`;}if(bundledAccessoryDelivery(i))return "Included with equipment delivery · No additional delivery or pickup fee";const p=products.find(p=>p.id===i.id);if(collectableRental(p)&&rentalCollection()==="pickup")return "Customer pickup · No delivery fee";if(["weekly","monthly"].includes(i.term))return "Delivery fee waived for weekly/monthly rental";const fee=itemDeliveryEstimate(i),quantity=deliveryQuantity(i);return `Delivery (${quantity} ${quantity===1?"item":"items"}): ${fee===null?"To be confirmed":money(deliveryFees[$("#areaSelect").value])+" × "+quantity+" = "+money(fee)}`}

