["#hourlyCheckoutNote","#hourlyContractNote"].forEach(selector=>$(selector).hidden=!hasHourlyEquipmentService());const fields=$("#jobDetailsFields");fields.hidden=!needsJobDetails();fields.disabled=!needsJobDetails();$("#checkoutItems").innerHTML=visibleCart().map(i=>{const p=products.find(x=>x.id===i.id);return `<div class="checkout-item ${p.operatorService?"operator-line":""} ${p.quoteOnly?"quote-line":""}"><div><b>${lineName(i,p)}</b><strong>${lineTotal(i,p)}</strong></div><small>${lineRate(i,p)}</small>${deliveryLine(i)?`<small class="item-delivery">${deliveryLine(i)}</small>`:""}</div>`}).join("");const quotePending=hasQuoteItems();$("#checkoutSubtotal").textContent=money(equipmentSubtotal())+(quotePending?" + quote":"");const d=deliveryEstimate(),discount=rewardDiscount(),operatorTotal=operatorSubtotal();$("#checkoutOperatorRow").hidden=!operatorTotal;$("#checkoutOperatorSubtotal").textContent=money(operatorTotal);$("#checkoutRewardRow").hidden=!discount;$("#checkoutRewardLabel").textContent=discount?`${rewardsAccount.tier} rewards (${discount}%)`:"Rewards discount";$("#checkoutRewardDiscount").textContent=`−${money(rewardSavings())}`;$("#checkoutRewardNote").textContent=quotePending?"Manual-price items are excluded from this estimate and will be confirmed with availability.":discount?`${rewardsAccount.tier} discount is applied to equipment and rounded to the nearest CI$1. Operator service is shown separately. Final availability and total are still confirmed manually.`:"Final availability and total are confirmed manually before fulfillment.";const outbound=outboundDeliveryEstimate(),pickup=collectionEstimate();$("#checkoutDeliveryLabel").textContent="Estimated delivery";$("#checkoutDelivery").textContent=outbound===null?"To be confirmed":outbound===0?"No delivery fee":money(outbound);$("#checkoutCollectionRow").hidden=!cart.some(collectionEligible);$("#checkoutCollection").textContent=pickup===null?"Select area":money(pickup);$("#checkoutTotal").textContent=mo